	knownrebecs {
		Pong pong;
	}
	statevars {
		int count;
	}

	Ping(Pong myPong) {
		count = 0;
		pong = myPong;
	}

	msgsrv startMessage {
		self.println("Ping started the game");
		pong.pingMessage();
	}

	msgsrv pongMessage {
		count = count + 1;
		self.println("Ping received pong " + count);
